fn interleave(s1: &Vec<i32>, s2: &Vec<i32>, s3: &Vec<i32>) -> Vec<i32> {
    // All three vectors must have the same length.
    let n = s1.len();
    assert_eq!(n, s2.len(), "s2 must have the same length as s1");
    assert_eq!(n, s3.len(), "s3 must have the same length as s1");

    // Preallocate the result to exactly 3 * n elements.
    let mut res = Vec::with_capacity(3 * n);

    // Interleave elements from s1, s2, and s3.
    for i in 0..n {
        res.push(s1[i]);
        res.push(s2[i]);
        res.push(s3[i]);
    }

    res
}

